// CentralDogmaGameContent.swift — generated mission data, validated before packaging.
import Foundation

struct CentralDogmaGameOption: Codable, Identifiable, Sendable {
    var id: String { payload }
    let label, payload, detail, symbol: String
    let asset: String?
}
struct CentralDogmaGameMilestone: Codable, Sendable { let title, body, badge: String }
struct CentralDogmaGameStep: Codable, Identifiable, Sendable {
    let id, kind, group, title, instruction, payload, target: String
    let options: [CentralDogmaGameOption]
    let learn: [String]
    let points: Int
    let hint, wrong, success: String
    let autoPayload: String?
    let sequenceIndex, codonIndex: Int?
    let uniqueGroup: String?
    let milestone: CentralDogmaGameMilestone?
}
struct CentralDogmaGameRegion: Codable, Identifiable, Sendable {let id, label, kind, sequence: String}
struct CentralDogmaGameMission: Codable, Identifiable, Sendable {
    let id, title, stop, preRNA, matureRNA, template: String
    let regions: [CentralDogmaGameRegion]
    let codons: [String]
    let steps: [CentralDogmaGameStep]
}
struct CentralDogmaGameGuide: Codable, Identifiable, Sendable {
    let id, title, caption: String
    let bullets: [String]
}
struct CentralDogmaGameData: Codable, Sendable {
    let version: Int
    let scope: String
    let missions: [CentralDogmaGameMission]
    let players: [CentralDogmaGameGuide]
